                    amount=tx.amount,
                    description=tx.description,
                    category=category,
                    imported_at=tx.imported_at,
                )
        new.append(tx)

    if new:
        store.add_many(new)
    logger.info("imported %d transactions from %s (%d duplicates, %d errors)",
                len(new), path, duplicates, len(errors))
